const botaoAbrirNavbarLateral=document.querySelector("#botao-abrir-navbar-lateral");const fundoNavbarLateral=document.querySelector("#fundo-navbar-lateral");const navbarLateral=document.querySelector("#navbar-lateral");const botaoFecharNavbarLateral=document.querySelector("#botao-fechar-navbar-lateral");const fundoModalMsg=document.querySelector("#fundo-modal-msg");const modalMsg=document.querySelector("#modal-msg");const txtModalMsg=document.querySelector("#txt-modal-msg");const botaoFecharModalMsg=document.querySelector("#botao-fechar-modal-msg");function alternarNavbarLateral(exibir=!1){[fundoNavbarLateral,navbarLateral].forEach(function(el){if(exibir){el.classList.remove("esconder")}else{el.classList.add("esconder")}})}
function alternarModalMsg(msg=""){[fundoModalMsg,modalMsg].forEach(function(el){el.classList.toggle("esconder")});txtModalMsg.textContent=msg}
window.addEventListener("pageshow",function(){alternarNavbarLateral()});window.addEventListener("resize",function(){if(this.innerWidth>=576){alternarNavbarLateral()}});botaoAbrirNavbarLateral.addEventListener("click",function(){alternarNavbarLateral(!0)});[fundoNavbarLateral,botaoFecharNavbarLateral].forEach(function(el){el.addEventListener("click",function(){alternarNavbarLateral()})});[fundoModalMsg,botaoFecharModalMsg].forEach(function(el){el.addEventListener("click",function(){alternarModalMsg()})})